            <h2>Ingredients</h2>
            <ul>${ingredients.map((ing: string) => `<li>${ing}</li>`).join('')}</ul>
            <h2>Instructions</h2>
            <p>${row.instructions}</p>
            <h2>Average Rating</h2>
            <p>${row.avgRating || 'No ratings yet'}</p>
          `;
          resolve(html);
        } else {
          resolve(null);
        }
      });
