            [recipeId, comment],
            function (err) {
              if (err) {
                reject(err);
              } else {
                resolve(true);
              }
            }
          );
        } else {
          resolve(false);
        }
      });
    });
  }

  rateRecipe(recipeId: string, rating: number): Promise<boolean> {
    return new Promise((resolve, reject) => {
      this.db.get(`SELECT id FROM recipes WHERE id = ?`, [recipeId], (err, row) => {
        if (err) {
          reject(err);
        } else if (row) {
          this.db.run(
            `INSERT INTO ratings (recipeId, rating) VALUES (?, ?)`,
            [recipeId, rating],
            function (err) {
              if (err) {
                reject(err);
              } else {
                this.db.all(
                  `SELECT AVG(rating) as avgRating FROM ratings WHERE recipeId = ?`,
                  [recipeId],
                  (err, rows) => {
                    if (err) {
                      reject(err);
                    } else {
                      const avgRating = rows[0].avgRating;
                      this.db.run(
                        `UPDATE recipes SET avgRating = ? WHERE id = ?`,
                        [avgRating, recipeId],
                        function (err) {
                          if (err) {
                            reject(err);
                          } else {
                            resolve(true);
                          }
                        }
                      );
                    }
                  }
                );
              }
            }
          );
        } else {
          resolve(false);
        }
      });
    });
